/* En paysage, le titre, l'accroche et le texte du héros restent visibles dès
   le premier écran au lieu d'être repoussés sous une hauteur fixe. */
@media (max-width: 900px) and (max-height: 620px) and (orientation: landscape) {
  [data-aurevia-site] .home-aurevia-hero:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)),
  [data-aurevia-site] .home-aurevia-hero.hero-aurevia:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)),
  [data-aurevia-site] .aurevia-page-hero.page-hero:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)) {
    height: auto;
    min-height: 100svh;
  }

  [data-aurevia-site] .home-aurevia-hero .hero-content:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)),
  [data-aurevia-site] .aurevia-page-hero-layout.container:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)) {
    min-height: 100svh;
    padding-block: 82px 24px;
    align-items: center;
  }

  [data-aurevia-site] .aurevia-page-hero .aurevia-page-hero-copy h1:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)) {
    font-size: clamp(2.85rem, 7vw, 4.2rem);
    line-height: .88;
  }

  [data-aurevia-site] .aurevia-page-hero .aurevia-page-hero-copy .eyebrow:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)) {
    margin-bottom: 10px;
  }

  [data-aurevia-site] .aurevia-page-hero .aurevia-page-hero-copy > p:last-child:where(:not([data-aurevia-original-hero], [data-aurevia-original-hero] *)) {
    max-width: 48rem;
    margin-top: 14px;
    font-size: .95rem;
    line-height: 1.45;
  }
}
